package com.sunpride.van.pos

import com.sunpride.van.data.*
import org.json.JSONArray
import org.json.JSONObject
import java.math.BigInteger

/** F-R03/F-502 v1 evaluator extension to the existing offline POS engine.
 * Canonical TPM precedence, residual stacking, half-up money and stable input-order centavo allocation.
 * Golden fixtures are generated by the server evaluator, not a second pricing authority. */
internal object GovernedPromotions {
    // Android 29/30 has BigInteger but not longValueExact (added in API 31).
    fun exact(value:BigInteger):Long {require(value.bitLength()<=63){"Promotion amount exceeds integer bounds"};return value.toLong()}
    private fun objects(a:JSONArray?):List<JSONObject> = if(a==null)emptyList()else (0 until a.length()).map(a::getJSONObject)
    private fun strings(a:JSONArray?):List<String> = if(a==null)emptyList()else (0 until a.length()).map(a::getString)
    private fun multiply(a:Long,b:Long)=BigInteger.valueOf(a).multiply(BigInteger.valueOf(b)).let(::exact)
    private fun percent(amount:Long,bps:Long)=BigInteger.valueOf(amount).multiply(BigInteger.valueOf(bps)).add(BigInteger.valueOf(5000)).divide(BigInteger.valueOf(10000)).let(::exact)
    private fun gross(price:Long,base:Long,scale:Long)=BigInteger.valueOf(price).multiply(BigInteger.valueOf(base)).add(BigInteger.valueOf(scale/2)).divide(BigInteger.valueOf(scale)).let(::exact)
    fun apply(cart:List<CartLine>,customer:Customer,products:Map<String,Product>,prices:List<PriceLine>,json:String,now:Long):PromotionResult {
        val config=JSONObject(json)
        val schemes=objects(config.optJSONArray("schemes"))
        require(schemes.size<=500&&cart.size<=100)
        val lines=cart.mapIndexedNotNull {i,l->products[l.productId]?.takeIf {l.quantityBase>0}?.let {p->
            val price=PriceResolver.resolve(p,prices,now,customer)
            PromotionLine(i+1,p,l.quantityBase,0,price,0,null,price?.let {gross(it.unitPriceMinor,l.quantityBase,p.quantityScale)})
        }}.toMutableList()
        val inputCount=lines.size
        val balances=lines.map {it.grossMinor}.toMutableList()
        val discounts=MutableList(inputCount){0L}
        val groups=mutableSetOf<String>();val blocked=mutableSetOf<String>();val applied=mutableListOf<String>()
        var exclusive=false
        val issues=mutableListOf<CheckoutIssue>()
        val ordered=schemes.sortedWith(compareBy<JSONObject>{it.optInt("precedence",100)}.thenBy{it.getString("code")})
        for(p in ordered){
            val from=p.getLong("effectiveFrom");val to=if(p.isNull("effectiveTo"))null else p.getLong("effectiveTo")
            if(now<from||to!=null&&now>=to)continue
            require(p.optInt("engine_version",1)==1)
            val rule=p.getJSONObject("rule");val kind=rule.getString("kind");val code=p.getString("code")
            val timing=p.optString("benefit_timing","on_invoice")
            val group=p.optString("exclusion_group").takeUnless {it.isBlank()||it=="null"}
            val stack=p.optString("stacking","exclusive")
            if(exclusive||code in blocked||group!=null&&group in groups||strings(p.optJSONArray("excludes")).any {it in applied}||stack=="exclusive"&&applied.isNotEmpty())continue
            val units=objects(rule.optJSONArray("components")).ifEmpty {listOfNotNull(rule.optJSONObject("buy")?:rule.optJSONObject("item"))}
            val listId=p.optString("price_list_id").takeUnless {it.isBlank()||it=="null"}
            fun matches(i:Int)=listId==null||config.optJSONObject("priceLists")?.optString(lines[i].product.productId)==listId
            val indexes=if(units.isNotEmpty())units.map {u->(0 until inputCount).firstOrNull {i->lines[i].product.productId==u.getString("productId")&&lines[i].product.uomCode==u.getString("uom")&&matches(i)}?:-1}
                else (0 until inputCount).filter(::matches)
            if(indexes.any {it<0||lines[it].price==null})continue
            val multiple=if(units.isEmpty())1L else units.indices.minOf {i->lines[indexes[i]].paidBase/multiply(units[i].getLong("quantity"),lines[indexes[i]].product.quantityScale)}
            if(multiple<1)continue
            if(kind=="basket"&&lines.take(inputCount).any {it.price==null})continue
            val available=indexes.fold(0L){n,i->Math.addExact(n,balances[i])}
            var discount=0L;var gift:JSONObject?=null
            when(kind){
                "percent_off"->discount=percent(available,rule.getLong("percentOffBasisPoints"))
                "value_off"->discount=multiply(rule.getLong("valueCentavos"),multiple)
                "quantity_off"->discount=multiply(multiply(checkNotNull(lines[indexes.first()].price).unitPriceMinor,rule.getLong("quantityOff")),multiple)
                "buy_x_get_y","bogo","free_goods"->gift=rule.getJSONObject("free")
                "bundle","combo"->{val normal=units.indices.fold(0L){n,i->Math.addExact(n,multiply(checkNotNull(lines[indexes[i]].price).unitPriceMinor,units[i].getLong("quantity")))};discount=multiply(maxOf(0,normal-rule.getLong("bundlePriceMinor")),multiple)}
                "slab"->{val line=lines[indexes.first()];val slab=objects(rule.getJSONArray("slabs")).lastOrNull {line.paidBase>=multiply(it.getLong("minQuantity"),line.product.quantityScale)};if(slab!=null)discount=percent(available,slab.getLong("percentOffBasisPoints"))}
                "basket"->{val qualifying=indexes.fold(0L){n,i->Math.addExact(n,lines[i].grossMinor)};if(qualifying>=rule.getLong("minSubtotalCentavos"))discount=if(rule.has("valueCentavos"))rule.getLong("valueCentavos")else percent(available,rule.getLong("percentOffBasisPoints"))}
                else->{issues+=CheckoutIssue(CheckoutProblem.PROMOTION_NEEDS_OFFICE);continue}
            }
            discount=minOf(discount,available)
            if(discount==0L&&gift==null)continue
            if(!p.isNull("campaign_version_id")&&p.optString("campaign_version_id").isNotBlank()){
                issues+=CheckoutIssue(CheckoutProblem.PROMOTION_NEEDS_OFFICE,indexes.firstOrNull()?.let {lines[it].product.productId});continue
            }
            val allocated=MutableList(inputCount){0L}
            if(available>0){
                for(i in indexes)allocated[i]=BigInteger.valueOf(discount).multiply(BigInteger.valueOf(balances[i])).divide(BigInteger.valueOf(available)).let(::exact)
                var remainder=discount-allocated.sum()
                for(i in indexes)if(remainder>0&&allocated[i]<balances[i]){allocated[i]++;remainder--}
            }
            for(i in 0 until inputCount){balances[i]-=allocated[i];if(timing=="on_invoice")discounts[i]=Math.addExact(discounts[i],allocated[i])}
            val quoted=QuotedPromotion(p.getString("id"),code,p.optString("name",code),kind)
            indexes.forEach {lines[it].promotion=quoted}
            gift?.let {g->
                check(timing=="on_invoice")
                val product=products[g.getString("productId")]
                val unitsMap=config.optJSONObject("units")?.optJSONObject(g.getString("productId"))
                val factor=unitsMap?.optString(g.getString("uom"))?.toLongOrNull() ?: product?.takeIf {it.uomCode==g.getString("uom")}?.quantityScale
                if(product==null||factor==null){issues+=CheckoutIssue(CheckoutProblem.PROMOTION_NEEDS_OFFICE,g.getString("productId"))}
                else{
                    val base=multiply(multiply(g.getLong("quantity"),multiple),factor)
                    // Canonical order.quote appends a separate free-goods line, even for a paid SKU.
                    lines+=PromotionLine(lines.size+1,product,0,base,null,0,quoted,0)
                }
            }
            applied+=code;if(group!=null)groups+=group;blocked+=strings(p.optJSONArray("excludes"));exclusive=stack=="exclusive"
        }
        for(i in 0 until inputCount)lines[i].discountMinor=discounts[i]
        return PromotionResult(lines,issues)
    }
}
